import base64, concurrent.futures, datetime, hashlib, json, pathlib, urllib.request
ROOT=pathlib.Path(__file__).parent
D=ROOT/'downloads'
JOBS=[
 {'name':'flutter','url':'https://storage.googleapis.com/flutter_infra_release/releases/stable/windows/flutter_windows_3.47.7-stable.zip','filename':'flutter-3.47.7.zip','algorithm':'sha256','expected':'c2c875da25a1a1448d18ee4e8f398b2f6fce888b4775d8f9130538e16d826cb4','limit':4*2**30},
 {'name':'node','url':'https://nodejs.org/dist/v24.22.1/node-v24.22.1-win-x64.zip','filename':'node-24.22.1.zip','algorithm':'sha256','expected':'d2046d28c2c3dcd211ac5145c0bf30e2047ef9dfb306693c8c6e2eccd8b95fa5','limit':300*2**20},
]
def get(url):
 return urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'YourOwn-Authorized-Isolated-Probe/0.1'}),timeout=60)
def download(job):
 result=dict(job); result['started_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat()
 partial=D/(job['filename']+'.partial'); verified=D/job['filename']; digest=hashlib.new(job['algorithm']); sha=hashlib.sha256(); size=0
 try:
  with get(job['url']) as response, partial.open('wb') as out:
   result['final_url']=response.url
   length=int(response.headers.get('Content-Length',0)); result['declared_length']=length
   if length>job['limit']: raise RuntimeError('Declared archive size exceeds review limit')
   while chunk:=response.read(1024*1024):
    size+=len(chunk)
    if size>job['limit']: raise RuntimeError('Archive exceeds review limit')
    out.write(chunk); digest.update(chunk); sha.update(chunk)
    if size%(64*2**20)==0: print(job['name'],size//2**20,'MiB',flush=True)
  actual=base64.b64encode(digest.digest()).decode() if job['algorithm']=='sha512' else digest.hexdigest()
  result.update(bytes=size,sha256=sha.hexdigest(),actual_digest=actual,integrity_matches=actual==job['expected'])
  if not result['integrity_matches']: raise RuntimeError('DIGEST MISMATCH: quarantined; do not extract or execute')
  partial.replace(verified); result['verified_file']=str(verified); result['status']='verified-bytes'
 except Exception as e:
  result.update(status='blocked',error=type(e).__name__+': '+str(e),bytes=size)
 result['ended_utc']=datetime.datetime.now(datetime.timezone.utc).isoformat()
 (ROOT/'evidence'/('download-'+job['name']+'.json')).write_text(json.dumps(result,indent=2),encoding='utf-8')
 print(job['name'],result['status'],result.get('error',''),flush=True)
 return result
try:
 with get('https://registry.npmjs.org/@pnpm%2Fexe.win32-x64/12.15.0') as response: raw=response.read()
 (ROOT/'evidence'/'pnpm-package-metadata.json').write_bytes(raw)
 meta=json.loads(raw); algorithm,expected=meta['dist']['integrity'].split('-',1)
 assert meta['name']=='@pnpm/exe.win32-x64' and meta['version']=='12.15.0' and algorithm=='sha512'
 JOBS.append({'name':'pnpm','url':meta['dist']['tarball'],'filename':'pnpm-12.15.0.tgz','algorithm':algorithm,'expected':expected,'limit':200*2**20})
except Exception as e: print('pnpm metadata blocked',type(e).__name__,str(e),flush=True)
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool: results=list(pool.map(download,JOBS))
(ROOT/'evidence'/'downloads.json').write_text(json.dumps(results,indent=2),encoding='utf-8')
print('No extraction/execution performed.',flush=True)

