"use client";
import { useState } from 'react';
import { QueryClient, QueryClientProvider, useQuery } from '@tanstack/react-query';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { HugeiconsIcon } from '@hugeicons/react';
import { Home01Icon } from '@hugeicons/core-free-icons';
const schema = z.object({ title: z.string().min(1) });
const defaults = { title: 'Synthetic only' };
function Content() {
  const query = useQuery({ queryKey: ['synthetic'], queryFn: async () => 7, initialData: 7 });
  const { register, handleSubmit, formState: { errors } } = useForm<z.infer<typeof schema>>({ resolver: zodResolver(schema), defaultValues: defaults });
  const [saved, setSaved] = useState(false);
  return <section className="rounded-3xl border p-6">
    <span aria-hidden="true"><HugeiconsIcon icon={Home01Icon} size={24} /></span>
    <p>Synthetic count: {query.data}</p>
    <form onSubmit={handleSubmit(() => setSaved(true))}>
      <label htmlFor="title">Probe title</label>
      <input id="title" defaultValue={defaults.title} {...register('title')} aria-invalid={!!errors.title} />
      <button type="submit" className="rounded-xl p-3">Validate synthetic input</button>
      <output>{saved ? 'Validated locally' : 'Not submitted'}</output>
    </form>
  </section>;
}
export default function ClientProbe() {
  const [client] = useState(() => new QueryClient());
  return <QueryClientProvider client={client}><Content /></QueryClientProvider>;
}

