import 'reflect-metadata';
import assert from 'node:assert/strict';
import { writeFileSync } from 'node:fs';
import { Controller, Get, Module } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { ApiOkResponse, ApiProperty, DocumentBuilder, SwaggerModule } from '@nestjs/swagger';

class ProbeResponse {
  @ApiProperty({ type: String, example: '9007199254740993' })
  exact!: string;
}
@Controller('probe')
class ProbeController {
  @Get()
  @ApiOkResponse({ type: ProbeResponse })
  read(): ProbeResponse { return { exact: '9007199254740993' }; }
}
@Module({ controllers: [ProbeController] })
class ProbeModule {}

async function main() {
  const app = await NestFactory.create(ProbeModule, { logger: false });
  try {
    const document = SwaggerModule.createDocument(app, new DocumentBuilder().setTitle('Synthetic probe').setVersion('0').build());
    const schema = document.components?.schemas?.ProbeResponse;
    assert(schema && 'properties' in schema);
    const property = schema.properties?.exact;
    assert(property && 'type' in property);
    assert.equal(property.type, 'string');
    assert(document.paths['/probe']?.get);
    writeFileSync('../../evidence/api-openapi.json', JSON.stringify(document, null, 2));
    await app.listen(0, '127.0.0.1');
    const url = await app.getUrl();
    assert(url.startsWith('http://127.0.0.1:'));
    const response = await fetch(`${url}/probe`);
    assert.equal(response.status, 200);
    assert.deepEqual(await response.json(), { exact: '9007199254740993' });
    console.log('PASS: decorators, OpenAPI string schema, loopback GET and exact synthetic string');
  } finally { await app.close(); }
}
void main().catch(error => { console.error(error); process.exitCode = 1; });

